// ============================================================
// BERICHT-TEXT NORMALISIEREN
// Führt beide Branches zusammen: Sprachnachricht (transkribiert)
// oder Textnachricht. Generiert Berichtsnummer + Metadaten.
// ============================================================

const trigger = $('Telegram Trigger').first().json;
const msg = trigger.message;

// Quelle bestimmen: kam der Input über den Whisper-Branch?
let berichtText;
let quelle;
if (msg.voice) {
  // Voice-Branch: Whisper-Ergebnis liegt im aktuellen Input
  berichtText = $input.first().json.text || '';
  quelle = 'Sprachnachricht';
} else {
  // Text-Branch: Text direkt aus der Telegram-Nachricht
  berichtText = msg.text || '';
  quelle = 'Textnachricht';
}

// Monteur-Name aus Telegram-Profil
const monteur = [msg.from.first_name, msg.from.last_name].filter(Boolean).join(' ') || msg.from.username || 'Unbekannt';

// Berichtsnummer generieren: AB-YYYY-XXXXX
const now = new Date();
const berichtsnummer = `AB-${now.getFullYear()}-${Math.floor(Math.random() * 90000) + 10000}`;

const datum = now.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' });
const uhrzeit = now.toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' });

return {
  berichtsnummer,
  datum,
  uhrzeit,
  monteur,
  quelle,
  berichtText,
  chatId: msg.chat.id,
  timestamp: now.toISOString()
};

