// ============================================================
// AI RESPONSE PARSEN
// Extrahiert den strukturierten Bericht und formatiert
// Arrays als Aufzählungen für Airtable + E-Mail
// ============================================================

const response = $input.first().json;
let rawContent = response.choices[0].message.content;

let ai;
try {
  ai = typeof rawContent === 'string' ? JSON.parse(rawContent) : rawContent;
} catch (e) {
  ai = {
    kunde_objekt: 'Nicht angegeben',
    auftrag: 'Konnte nicht automatisch ausgewertet werden',
    durchgefuehrte_arbeiten: [],
    verwendetes_material: [],
    zeitaufwand_stunden: 0,
    status: 'Teilweise erledigt',
    offene_punkte: ['Bericht manuell prüfen — automatische Auswertung fehlgeschlagen'],
    maengel_hinweise: '',
    folgetermin_noetig: true,
    zusammenfassung: 'Die Notiz konnte nicht automatisch strukturiert werden. Original-Text liegt in Airtable vor.'
  };
}

// Status normalisieren für Airtable Single-Select
const statusErlaubt = ['Abgeschlossen', 'Teilweise erledigt', 'Folgetermin nötig'];
const status = statusErlaubt.includes(ai.status) ? ai.status : 'Teilweise erledigt';

// Arrays als Aufzählungstext
const alsListe = (arr) => Array.isArray(arr) && arr.length > 0 ? '• ' + arr.join('\n• ') : '—';

const meta = $('Bericht-Text normalisieren').first().json;

return {
  ...meta,
  kundeObjekt: ai.kunde_objekt || 'Nicht angegeben',
  auftrag: ai.auftrag || '',
  arbeitenListe: alsListe(ai.durchgefuehrte_arbeiten),
  materialListe: alsListe(ai.verwendetes_material),
  zeitaufwand: Number(ai.zeitaufwand_stunden) || 0,
  status,
  offenePunkteListe: alsListe(ai.offene_punkte),
  maengel: ai.maengel_hinweise || '',
  folgeterminNoetig: ai.folgetermin_noetig ? 'Ja' : 'Nein',
  zusammenfassung: ai.zusammenfassung || ''
};

